//! Display-width primitives shared by the toolkit.
//!
//! Go's Charm stack uses three different width libraries:
//!
//! * `clipperhouse/displaywidth` (+ `uax29` graphemes) behind `x/ansi`
//!   (`ansi.StringWidth`, `Truncate`, `lipgloss.Width`, wrapping, ...);
//! * `rivo/uniseg` (`textinput`, lipgloss border sizes, `termenv.Style.Width`);
//! * `mattn/go-runewidth` (`textinput` horizontal scrolling).
//!
//! The per-codepoint properties of all three were extracted from the Go
//! libraries into [`tables`] (generated by `tools/paritygen/tuikit`). Grapheme
//! clustering uses `unicode-segmentation` (Unicode 17, the same version as
//! `uax29` v2.7.0). `uniseg` v0.4.7 implements Unicode 15.0 clustering; the
//! only differences are clusters involving characters or rules added after
//! 15.0 (e.g. Indic conjunct breaks), none of which the game prints.

mod tables;

use std::sync::OnceLock;
use unicode_segmentation::UnicodeSegmentation;

/// Raw property bits of a codepoint (see `tables.rs` header):
/// bits 0-1 displaywidth property, 2-4 uniseg width, 5 uniseg
/// Extended_Pictographic, 6-7 runewidth (narrow), 8-9 runewidth (East Asian).
fn props(c: char) -> u16 {
    let cp = c as u32;
    let t = tables::RANGES;
    // Last entry with start <= cp.
    let idx = t.partition_point(|&(start, _)| start <= cp);
    if idx == 0 {
        0
    } else {
        t[idx - 1].1
    }
}

/// displaywidth property values (0 default, 1 zero width).
pub(crate) const DW_WIDE: u8 = 2;
pub(crate) const DW_AMBIGUOUS: u8 = 3;

pub(crate) fn dw_prop(c: char) -> u8 {
    (props(c) & 3) as u8
}

/// rivo/uniseg `runeWidth` of a single rune with its own grapheme property.
pub(crate) fn uniseg_rune_width(c: char) -> i32 {
    ((props(c) >> 2) & 7) as i32
}

fn uniseg_is_extpict(c: char) -> bool {
    props(c) & (1 << 5) != 0
}

fn env_bool(name: &str) -> Option<bool> {
    // strconv.ParseBool
    match std::env::var(name).ok()?.as_str() {
        "1" | "t" | "T" | "TRUE" | "true" | "True" => Some(true),
        "0" | "f" | "F" | "FALSE" | "false" | "False" => Some(false),
        _ => None,
    }
}

/// `x/ansi` (method.go init): `RUNEWIDTH_EASTASIAN` parsed with ParseBool.
pub(crate) fn ansi_east_asian() -> bool {
    static EA: OnceLock<bool> = OnceLock::new();
    *EA.get_or_init(|| env_bool("RUNEWIDTH_EASTASIAN") == Some(true))
}

/// go-runewidth `handleEnv`/`IsEastAsian` for `DefaultCondition`.
pub(crate) fn runewidth_east_asian() -> bool {
    static EA: OnceLock<bool> = OnceLock::new();
    *EA.get_or_init(|| {
        let env = std::env::var("RUNEWIDTH_EASTASIAN").unwrap_or_default();
        if !env.is_empty() {
            return env == "1";
        }
        let get = |k: &str| std::env::var(k).unwrap_or_default();
        let mut locale = get("LC_ALL");
        if locale.is_empty() {
            locale = get("LC_CTYPE");
        }
        if locale.is_empty() {
            locale = get("LANG");
        }
        is_east_asian_locale(&locale)
    })
}

fn is_east_asian_locale(locale: &str) -> bool {
    if locale == "POSIX" || locale == "C" {
        return false;
    }
    let lb = locale.as_bytes();
    if lb.len() > 1 && lb[0] == b'C' && (lb[1] == b'.' || lb[1] == b'-') {
        return false;
    }
    // reLoc = `^[a-z][a-z][a-z]?(?:_[A-Z][A-Z])?\.(.+)`
    let mut charset = locale.to_lowercase();
    if let Some(cs) = match_re_loc(locale) {
        charset = cs.to_lowercase();
    }
    if charset.ends_with("@cjk_narrow") {
        return false;
    }
    if let Some(pos) = charset.find('@') {
        charset.truncate(pos);
    }
    let max = match charset.as_str() {
        "utf-8" | "utf8" => 6,
        "jis" => 8,
        "eucjp" => 3,
        "euckr" | "euccn" | "sjis" | "cp932" | "cp51932" | "cp936" | "cp949" | "cp950" | "big5"
        | "gbk" | "gb2312" => 2,
        _ => 1,
    };
    max > 1
        && (!charset.starts_with('u')
            || locale.starts_with("ja")
            || locale.starts_with("ko")
            || locale.starts_with("zh"))
}

/// Go regexp `^[a-z][a-z][a-z]?(?:_[A-Z][A-Z])?\.(.+)`: the capture group.
fn match_re_loc(locale: &str) -> Option<&str> {
    let lb = locale.as_bytes();
    let n = lb.len();
    let lower = |j: usize| j < n && lb[j].is_ascii_lowercase();
    let upper = |j: usize| j < n && lb[j].is_ascii_uppercase();
    if !(lower(0) && lower(1)) {
        return None;
    }
    let mut prefixes = Vec::new();
    if lower(2) {
        prefixes.push(3);
    }
    prefixes.push(2);
    for nl in prefixes {
        for underscore in [true, false] {
            let mut j = nl;
            if underscore {
                if !(j < n && lb[j] == b'_' && upper(j + 1) && upper(j + 2)) {
                    continue;
                }
                j += 3;
            }
            if j < n && lb[j] == b'.' && j + 1 < n {
                return locale.get(j + 1..);
            }
        }
    }
    None
}

/// go-runewidth `RuneWidth` with `DefaultCondition` (StrictEmojiNeutral).
pub fn runewidth_rune_width(c: char) -> i32 {
    let p = props(c);
    if runewidth_east_asian() {
        ((p >> 8) & 3) as i32
    } else {
        ((p >> 6) & 3) as i32
    }
}

/// Returns the byte length of the first extended grapheme cluster of `s`
/// (`uax29` `graphemes.FromString(s).First()`).
pub fn first_grapheme_len(s: &str) -> usize {
    s.graphemes(true).next().map(|g| g.len()).unwrap_or(0)
}

/// Byte-slice variant: clusters the longest valid UTF-8 prefix of `b`
/// (growing a window so that long strings are not re-validated each call).
pub(crate) fn first_grapheme_len_bytes(b: &[u8]) -> usize {
    let mut window = 64usize;
    loop {
        let end = window.min(b.len());
        let valid = match std::str::from_utf8(&b[..end]) {
            Ok(s) => s,
            Err(e) => {
                let v = e.valid_up_to();
                // valid_up_to is a char boundary
                std::str::from_utf8(&b[..v]).unwrap_or("")
            }
        };
        if valid.is_empty() {
            // Invalid UTF-8 at the start: uax29 yields a single byte.
            return if b.is_empty() { 0 } else { 1 };
        }
        let n = first_grapheme_len(valid);
        if n < valid.len() || end == b.len() || valid.len() < end {
            return n;
        }
        window *= 4;
    }
}

/// displaywidth `asciiWidth`.
fn ascii_width(b: u8) -> i32 {
    if b <= 0x1F || b == 0x7F {
        0
    } else {
        1
    }
}

const PROPERTY_WIDTHS: [i32; 4] = [1, 0, 2, 1];

/// displaywidth `graphemeWidth` (with `Options{EastAsianWidth: ea}`).
fn dw_grapheme_width(s: &str, ea: bool) -> i32 {
    let b = s.as_bytes();
    if b.is_empty() {
        return 0;
    }
    if b.len() == 1 {
        return ascii_width(b[0]);
    }
    if b[0] <= 0x1F {
        return 0;
    }
    let mut chars = s.chars();
    let first = chars.next().unwrap_or('\0');
    let sz = first.len_utf8();
    let mut prop = dw_prop(first);
    if prop != DW_WIDE
        && b.len() >= sz + 3
        && b[sz] == 0xEF
        && b[sz + 1] == 0xB8
        && b[sz + 2] == 0x8F
    {
        prop = DW_WIDE;
    }
    if ea && prop == DW_AMBIGUOUS {
        prop = DW_WIDE;
    }
    PROPERTY_WIDTHS[prop as usize]
}

/// displaywidth `printableASCIILength`.
fn printable_ascii_length(b: &[u8]) -> usize {
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if !(0x20..=0x7E).contains(&c) {
            break;
        }
        i += 1;
    }
    if i > 0 && i < b.len() && b[i] >= 0x80 {
        i -= 1;
    }
    i
}

/// displaywidth `Options.String` with the `x/ansi` options
/// (`EastAsianWidth` from `RUNEWIDTH_EASTASIAN`).
pub fn displaywidth_string(s: &str) -> i32 {
    displaywidth_string_opts(s, ansi_east_asian())
}

pub(crate) fn displaywidth_string_opts(s: &str, ea: bool) -> i32 {
    let b = s.as_bytes();
    let mut width = 0;
    let mut pos = 0;
    while pos < b.len() {
        let ascii_len = printable_ascii_length(&b[pos..]);
        if ascii_len > 0 {
            width += ascii_len as i32;
            pos += ascii_len;
            continue;
        }
        let start = pos;
        for g in s[pos..].graphemes(true) {
            width += dw_grapheme_width(g, ea);
            pos += g.len();
            if pos < b.len() && (0x20..=0x7E).contains(&b[pos]) {
                break;
            }
        }
        if pos == start {
            pos += 1;
        }
    }
    width
}

const VS15: char = '\u{FE0E}';
const VS16: char = '\u{FE0F}';

fn is_regional_indicator(c: char) -> bool {
    ('\u{1F1E6}'..='\u{1F1FF}').contains(&c)
}

fn is_hangul_l(c: char) -> bool {
    ('\u{1100}'..='\u{115F}').contains(&c) || ('\u{A960}'..='\u{A97C}').contains(&c)
}

/// rivo/uniseg width of one grapheme cluster (`FirstGraphemeClusterInString`).
pub fn uniseg_cluster_width(cluster: &str) -> i32 {
    let mut chars = cluster.chars();
    let Some(first) = chars.next() else {
        return 0;
    };
    let mut width = uniseg_rune_width(first);
    let ext = uniseg_is_extpict(first);
    let skip = is_regional_indicator(first) || is_hangul_l(first);
    for r in chars {
        if ext {
            if r == VS15 {
                width = 1;
            } else if r == VS16 {
                width = 2;
            }
        } else if !skip {
            width += uniseg_rune_width(r);
        }
    }
    width
}

/// rivo/uniseg `FirstGraphemeClusterInString`: (cluster, rest, width).
pub fn uniseg_first_grapheme_cluster(s: &str) -> (&str, &str, i32) {
    let n = first_grapheme_len(s);
    let (c, rest) = s.split_at(n);
    (c, rest, uniseg_cluster_width(c))
}

/// rivo/uniseg `StringWidth`.
pub fn uniseg_string_width(s: &str) -> i32 {
    s.graphemes(true).map(uniseg_cluster_width).sum()
}

/// Go `unicode.IsSpace`.
pub fn go_is_space(r: char) -> bool {
    matches!(
        r,
        '\t' | '\n'
            | '\u{0B}'
            | '\u{0C}'
            | '\r'
            | ' '
            | '\u{85}'
            | '\u{A0}'
            | '\u{1680}'
            | '\u{2000}'
            ..='\u{200A}' | '\u{2028}' | '\u{2029}' | '\u{202F}' | '\u{205F}' | '\u{3000}'
    )
}

/// Go `unicode.IsLower` (exact for ASCII; general category `Ll`
/// approximated by the Lowercase property for other scripts).
pub fn go_is_lower(r: char) -> bool {
    if r.is_ascii() {
        return r.is_ascii_lowercase();
    }
    r.is_lowercase() && r.to_uppercase().next() != Some(r)
}

/// Go `unicode.IsUpper` (exact for ASCII; approximated elsewhere).
pub fn go_is_upper(r: char) -> bool {
    if r.is_ascii() {
        return r.is_ascii_uppercase();
    }
    r.is_uppercase() && r.to_lowercase().next() != Some(r)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic_widths() {
        assert_eq!(displaywidth_string("hello"), 5);
        assert_eq!(displaywidth_string("日本"), 4);
        assert_eq!(displaywidth_string("⚠️"), 2);
        assert_eq!(displaywidth_string("⚠"), 1);
        assert_eq!(displaywidth_string("🔊"), 2);
        assert_eq!(uniseg_string_width("⚠️"), 2);
        assert_eq!(uniseg_string_width("│"), 1);
        assert_eq!(runewidth_rune_width('a'), 1);
    }

    #[test]
    fn locale_detection() {
        assert!(!is_east_asian_locale("C"));
        assert!(!is_east_asian_locale("en_US.UTF-8"));
        assert!(is_east_asian_locale("ja_JP.UTF-8"));
        assert!(is_east_asian_locale("zh_CN.gbk"));
        assert!(!is_east_asian_locale("ja_JP.UTF-8@cjk_narrow"));
    }
}
